// Covers: FEAT-GEO-003. New coverage (ADR-0006 decision 2's corpus test); docs/specs/geo.md §11.3.
//
// projection_expected.csv (see tests/fixtures/zmp/README.md) is a CROSS-CHECK, not an independent
// oracle: it is generated by tools/gen_projection_expected.py, a Python transcription of
// docs/specs/geo.md §2.3/§2.4's pseudo-code (scripted, not copy-pasted from the C++), by the same
// author, in the same session, against the same spec text the C++ also implements. It cannot catch
// a shared misreading of the spec's source (u_ProjectionTypeFactorySimple.pas); the legacy Windows
// binary was never run to confirm either one. Its value is in catching a C++/spec divergence and in
// pinning a regression. Regenerate/verify with `tools/gen_projection_expected.py [--check]`.
//
// Deviation from the spec's literal reference counts (docs/specs/geo.md §2.4, §11.3, corrected by
// the T-0016 review): six params.txt files carry `EPSG=4326` in `[PARAMS]` **and** `EPSG=3785` in
// a separate `[ViewInfo]` section (e.g. GoogleEarth.Earth.zmp/params.txt:9 vs :18) — there is no
// duplicate key within `[PARAMS]`, so core::IniFile's section-scoped lookup simply never sees the
// `[ViewInfo]` value. A naive substring count of "EPSG=3785" over raw file bytes (132) conflates
// the two sections and does not distinguish them from a real, `[PARAMS]`-scoped 3785 (126). The
// distribution test below asserts the CSV's real, section-scoped counts; docs/specs/geo.md §11.3
// authorizes exactly this adjustment ("the expected CSV is the authority"). Two ad-hoc maps beyond
// the spec's named eleven were also found in the actual harvested fixtures (both Atlogis Landsat
// scripts, projection=3 with sradiusb explicitly set to sradiusa's value, 6378137, which misses the
// ellipsoid tolerance) and are asserted here too.
#include "cg/core/config_provider_ini.h"
#include "cg/core/ini_file.h"
#include "cg/geo/datum.h"
#include "cg/geo/projection_type_factory.h"

#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <QFileInfoList>
#include <QTextStream>

#include <gtest/gtest.h>

#include <functional>
#include <memory>
#include <set>
#include <string>
#include <vector>

#include "fixture_path.h"

using cg::core::ConfigProviderIni;
using cg::core::IConfigProviderPtr;
using cg::core::IniFile;
using cg::geo::DatumFactory;
using cg::geo::HashSeed;
using cg::geo::ProjectionTypeFactory;
using cg::geo::UnexpectedProjectionType;

namespace {

// docs/specs/geo.md §2.4's `byConfig(const core::IConfigProvider*)` expects a provider already
// scoped to the ZMP's `[PARAMS]` section (T-0016 review, Q-A). nullptr (no `[PARAMS]` section at
// all) falls through to byConfig's own `config == nullptr` defaulting, same as legacy's
// `AConfig <> nil` guard.
IConfigProviderPtr paramsSectionOf(const QString& paramsPath) {
    const auto provider = ConfigProviderIni::open(paramsPath);
    if (!provider.has_value()) {
        return nullptr;
    }
    return (*provider)->subItem(u"PARAMS");
}

struct ExpectedRow {
    QString name;
    QString klass;
    int projectionEpsg = 0;
    int datumEpsg = 0;
};

QString zmpRoot() {
    return cgGeoFixture(QStringLiteral("zmp/sas.maps"));
}
QString expectedCsvPath() {
    return cgGeoFixture(QStringLiteral("zmp/projection_expected.csv"));
}

std::vector<ExpectedRow> loadExpected() {
    std::vector<ExpectedRow> rows;
    QFile f(expectedCsvPath());
    if (!f.open(QIODevice::ReadOnly | QIODevice::Text)) {
        return rows;
    }
    QTextStream in(&f);
    bool first = true;
    while (!in.atEnd()) {
        const QString line = in.readLine();
        if (first) {
            first = false;
            continue; // header
        }
        if (line.isEmpty())
            continue;
        const QStringList cols = line.split(u',');
        if (cols.size() < 4)
            continue;
        ExpectedRow row;
        row.name = cols[0];
        row.klass = cols[1];
        row.projectionEpsg = cols[2].toInt();
        row.datumEpsg = cols[3].toInt();
        rows.push_back(row);
    }
    return rows;
}

ProjectionTypeFactory makeFactory() {
    return ProjectionTypeFactory{HashSeed{}, std::make_shared<const DatumFactory>(HashSeed{})};
}

} // namespace

TEST(ZmpProjectionCorpus, EveryStockZmpResolvesWithoutThrowing) {
    CG_SKIP_IF_NO_CORPUS();
    const auto expected = loadExpected();
    ASSERT_FALSE(expected.empty()) << "projection_expected.csv missing or empty at "
                                   << expectedCsvPath().toStdString();
    auto factory = makeFactory();
    int failures = 0;
    for (const auto& row : expected) {
        const QString paramsPath = QDir(zmpRoot()).filePath(row.name + QStringLiteral("/params.txt"));
        const auto params = paramsSectionOf(paramsPath);
        ASSERT_TRUE(params != nullptr) << paramsPath.toStdString();
        try {
            (void)factory.byConfig(params.get());
        } catch (const UnexpectedProjectionType& e) {
            ++failures;
            ADD_FAILURE() << row.name.toStdString() << ": " << e.what();
        }
    }
    EXPECT_EQ(failures, 0);
}

TEST(ZmpProjectionCorpus, ResolvedEpsgMatchesTheExpectedTable) {
    CG_SKIP_IF_NO_CORPUS();
    const auto expected = loadExpected();
    ASSERT_FALSE(expected.empty());
    auto factory = makeFactory();
    for (const auto& row : expected) {
        const QString paramsPath = QDir(zmpRoot()).filePath(row.name + QStringLiteral("/params.txt"));
        const auto params = paramsSectionOf(paramsPath);
        ASSERT_TRUE(params != nullptr) << paramsPath.toStdString();
        const auto type = factory.byConfig(params.get());
        EXPECT_EQ(type->projectionEpsg(), row.projectionEpsg) << row.name.toStdString();
        EXPECT_EQ(type->datum()->epsg(), row.datumEpsg) << row.name.toStdString();
    }
}

TEST(ZmpProjectionCorpus, DistributionMatchesTheReferenceInstall) {
    CG_SKIP_IF_NO_CORPUS();
    // Raw key distribution (independent of resolution), matching docs/specs/geo.md §2.4 exactly
    // for `projection=`, and the CORRECTED `EPSG=` counts for the six files with a `[ViewInfo]`
    // EPSG alongside the `[PARAMS]` one (see the file header comment above).
    const QDir root(zmpRoot());
    const QFileInfoList entries =
        root.entryInfoList({QStringLiteral("*.zmp")}, QDir::Dirs | QDir::NoDotAndDotDot);
    int projection1 = 0, projection2 = 0, projection3 = 0, projectionAbsent = 0;
    int epsg3785 = 0, epsg3395 = 0, epsg3857 = 0, epsg4326 = 0, epsgAbsent = 0;
    int total = 0;

    std::function<void(const QDir&)> walk = [&](const QDir& dir) {
        for (const QFileInfo& info : dir.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot)) {
            if (info.fileName().endsWith(QStringLiteral(".zmp"))) {
                ++total;
                const auto loaded =
                    IniFile::fromFile(QDir(info.filePath()).filePath(QStringLiteral("params.txt")));
                ASSERT_TRUE(loaded.has_value());
                if (!loaded->hasKey(u"PARAMS", u"projection")) {
                    ++projectionAbsent;
                } else {
                    switch (loaded->readInt(u"PARAMS", u"projection", 1)) {
                    case 1:
                        ++projection1;
                        break;
                    case 2:
                        ++projection2;
                        break;
                    case 3:
                        ++projection3;
                        break;
                    default:
                        break;
                    }
                }
                if (!loaded->hasKey(u"PARAMS", u"EPSG")) {
                    ++epsgAbsent;
                } else {
                    switch (loaded->readInt(u"PARAMS", u"EPSG", 0)) {
                    case 3785:
                        ++epsg3785;
                        break;
                    case 3395:
                        ++epsg3395;
                        break;
                    case 3857:
                        ++epsg3857;
                        break;
                    case 4326:
                        ++epsg4326;
                        break;
                    default:
                        break;
                    }
                }
            } else {
                walk(QDir(info.filePath()));
            }
        }
    };
    walk(root);

    EXPECT_EQ(total, 514);
    EXPECT_EQ(projection1, 316);
    EXPECT_EQ(projection2, 25);
    EXPECT_EQ(projection3, 3);
    EXPECT_EQ(projectionAbsent, 170);
    EXPECT_EQ(epsg3395, 23);
    EXPECT_EQ(epsg3857, 11);
    EXPECT_EQ(epsg4326, 6);
    // core::IniFile's `[PARAMS]`-scoped read never sees the six files' `[ViewInfo]` EPSG=3785:
    // 126, not the section-blind substring count of 132.
    EXPECT_EQ(epsg3785, 126);
    EXPECT_EQ(epsgAbsent, 348);
}

TEST(ZmpProjectionCorpus, AdHocMapsGetEpsgZero) {
    CG_SKIP_IF_NO_CORPUS();
    const std::set<std::string> expectedAdHoc = {
        "_Space/Mars.zmp",
        "_Space/Moon.zmp",
        "_Space/nasaLunarOrbiter.zmp",
        "_Space/nasaMarsMOLA.zmp",
        "_Space/nasaMarsTHEMIS.zmp",
        "_Space/space_mars_elevation.zmp",
        "_Space/space_mars_infrared.zmp",
        "_Space/space_moon_terrain.zmp",
        "_broken_maps/Others/geogarage_com_route.zmp",
        "_broken_maps/Others/mpoisk.ru.zmp",
        "_broken_maps/Local/igis-izhevsk.zmp",
        // Two more found in the real harvested corpus beyond the spec's named eleven (see the
        // file header comment): projection=3 with sradiusb explicitly set to sradiusa's value,
        // missing the ellipsoid tolerance.
        "_broken_maps/Atlogis/atlogis_LS7.zmp",
        "_broken_maps/Atlogis/atlogis_Landsat5.zmp",
    };
    const auto expected = loadExpected();
    ASSERT_FALSE(expected.empty());
    auto factory = makeFactory();
    std::set<std::string> actualAdHoc;
    for (const auto& row : expected) {
        if (row.projectionEpsg == 0) {
            actualAdHoc.insert(row.name.toStdString());
        }
    }
    EXPECT_EQ(actualAdHoc, expectedAdHoc);

    // igis-izhevsk.zmp specifically: sradiusa = sradiusb = 4624384.
    const QString paramsPath =
        QDir(zmpRoot()).filePath(QStringLiteral("_broken_maps/Local/igis-izhevsk.zmp/params.txt"));
    const auto params = paramsSectionOf(paramsPath);
    ASSERT_TRUE(params != nullptr);
    const auto type = factory.byConfig(params.get());
    EXPECT_EQ(type->projectionEpsg(), 0);
    EXPECT_DOUBLE_EQ(type->datum()->radiusA(), 4624384.0);
    EXPECT_DOUBLE_EQ(type->datum()->radiusB(), 4624384.0);
}
